echo "import asyncio
from aiohttp import web

def make_request(method, path):
    return web.Request(method=method, path=path, headers={})

async def test_configure_response():
    req = make_request('GET', '/')
    resp = web.StreamResponse(req)
    resp.content_type = 'application/octet-stream'
    try:
        resp.charset = 'utf-8'
    except Exception as e:
        print(f"Error: {e}")

asyncio.run(test_configure_response())" > test_reproduce.py

